using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEngine;
// Real rig starts, stops and changes direction through the ordinary input path.
public sealed class StartupTests : MonoBehaviour {
 public static bool UseAI;static bool booted;static readonly HashSet<KeyCode> keys=new HashSet<KeyCode>();
 public static bool ReadKey(KeyCode k){return keys.Contains(k);}public static bool ReadDown(KeyCode k){return false;}
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=Path.Combine(Application.dataPath,"..","startup-test.ini");var o=new GameObject("StartupTests");DontDestroyOnLoad(o);o.AddComponent<StartupTests>();}
 [Serializable]public class Sample {public string actor;public int mode;public bool backward;public float responseTime,speed100,distance100,speed200,restartTime,reverseTime,footLift,peakLean,jointError;}
 [Serializable]public class Results {public List<Sample> samples=new List<Sample>();public int checks,failures;}
 Results result=new Results();Component fan,zhao;Type pt;Rigidbody2D ball;float scale;const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic;
 Rigidbody2D Body(Component p){return (Rigidbody2D)pt.GetField("rb").GetValue(p);}
 void Move(Component p,Vector2 at){p.transform.position+=(Vector3)(at-Body(p).position);foreach(var b in p.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
 float Error(Component p){float e=0;foreach(var j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)e=Mathf.Max(e,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return e;}
 void Press(bool isFan,float dir){keys.Clear();keys.Add(ControlBindings.Get(isFan,dir>0?GameControlAction.Right:GameControlAction.Left));}
 IEnumerator Scene(int mode){keys.Clear();UseAI=false;Time.timeScale=1;ControlBindings.ResetDefaults();AbilityMode.Reset();AbilityMode.Enabled=mode==2;PlayerSkills.Enabled=mode==1;if(mode==2)foreach(var b in AbilityMode.Builds){b.Levels[0]=4;b.Levels[1]=0;b.Levels[2]=0;b.Purchased=1<<7;}typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.4f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;ball.gravityScale=0;ball.velocity=Vector2.zero;ball.position=new Vector2(0,4*scale);GameAIMod.OnBallReset();foreach(var a in FindObjectsOfType<Animator>())a.cullingMode=AnimatorCullingMode.AlwaysAnimate;}
 IEnumerator Case(int mode,bool isFan,bool back){yield return Scene(mode);Component actor=isFan?fan:zhao;float facing=isFan?1:-1,dir=facing*(back?-1:1);Move(actor,new Vector2(0,Body(actor).position.y));Move(isFan?zhao:fan,new Vector2(-dir*7*scale,Body(isFan?zhao:fan).position.y));ball.position=new Vector2(facing*3*scale,4*scale);yield return new WaitForSeconds(.15f);Move(actor,new Vector2(0,Body(actor).position.y));float startX=Body(actor).position.x,start=Time.fixedTime;Transform left=actor.transform.Find("L_LowLeg"),right=actor.transform.Find("R_LowLeg");float floor=Mathf.Min(left.position.y,right.position.y);Sample s=new Sample();s.actor=actor.name;s.mode=mode;s.backward=back;s.responseTime=s.restartTime=s.reverseTime=1;
 Press(isFan,dir);for(int i=0;i<40;i++){yield return new WaitForFixedUpdate();float elapsed=Time.fixedTime-start,v=dir*Body(actor).velocity.x;if(i==0){var manager=FindObjectOfType(pt.Assembly.GetType("GameManager"));Debug.Log("STARTUP INPUT axis="+ControlBindings.GetHorizontal(actor)+" bridged="+GameAIMod.GetAxis("Horizontal",actor)+" anim="+((Animator)pt.GetField("anim").GetValue(actor)).GetFloat("Horizontal")+" stopping="+manager.GetType().GetField("isStopping").GetValue(manager));}if(v>1f*scale&&s.responseTime==1)s.responseTime=elapsed;if(elapsed>=.099f&&s.speed100==0){s.speed100=v/scale;s.distance100=dir*(Body(actor).position.x-startX)/scale;}if(elapsed>=.199f&&s.speed200==0)s.speed200=v/scale;s.footLift=Mathf.Max(s.footLift,(Mathf.Max(left.position.y,right.position.y)-floor)/scale);s.peakLean=Mathf.Max(s.peakLean,Mathf.Abs(Mathf.DeltaAngle(Body(actor).rotation,0)));s.jointError=Mathf.Max(s.jointError,Error(actor));}
 keys.Clear();yield return new WaitForSeconds(.25f);Move(actor,new Vector2(0,Body(actor).position.y));start=Time.fixedTime;Press(isFan,dir);for(int i=0;i<15;i++){yield return new WaitForFixedUpdate();if(dir*Body(actor).velocity.x>1f*scale&&s.restartTime==1)s.restartTime=Time.fixedTime-start;s.jointError=Mathf.Max(s.jointError,Error(actor));}
 start=Time.fixedTime;Press(isFan,-dir);for(int i=0;i<25;i++){yield return new WaitForFixedUpdate();if(-dir*Body(actor).velocity.x>1f*scale&&s.reverseTime==1)s.reverseTime=Time.fixedTime-start;s.jointError=Mathf.Max(s.jointError,Error(actor));s.peakLean=Mathf.Max(s.peakLean,Mathf.Abs(Mathf.DeltaAngle(Body(actor).rotation,0)));}keys.Clear();
 bool pass=s.responseTime<.3f&&s.restartTime<.3f&&s.reverseTime<.5f&&s.footLift>.08f&&s.peakLean<45&&s.jointError<.6f;result.checks++;if(!pass)result.failures++;result.samples.Add(s);Debug.Log("ABILITY "+(pass?"PASS ":"FAIL ")+"startup mode="+mode+" actor="+actor.name+" back="+back+" response="+s.responseTime+" speed100="+s.speed100+" dist100="+s.distance100+" speed200="+s.speed200+" restart="+s.restartTime+" reverse="+s.reverseTime+" lift="+s.footLift+" lean="+s.peakLean+" joints="+s.jointError);}
 IEnumerator Display(){Type settings=typeof(ControlBindings);PropertyInfo show=settings.GetProperty("ShowSkillAnimations");MethodInfo set=settings.GetMethod("SetSkillAnimations");if(show==null||set==null)yield break;for(int mode=1;mode<=2;mode++){yield return Scene(mode);ball.position=new Vector2(3*scale,4*scale);float physics=PlayerMovement.GetMovementForce(100,fan);set.Invoke(null,new object[]{false});ControlBindings.Reload();bool persisted=!(bool)show.GetValue(null,null);if(mode==1)PlayerSkills.NotifyMovement(fan,1);else AbilityMode.ShowSkill(fan,7);yield return new WaitForSeconds(.1f);bool hidden=!(bool)show.GetValue(null,null);set.Invoke(null,new object[]{true});yield return new WaitForSeconds(.1f);Component owner=mode==1?(Component)fan.GetComponent<PlayerSkills>():fan.GetComponent<BuildPlayer>();float[] active=(float[])owner.GetType().GetField("effects",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(owner);bool visible=(bool)show.GetValue(null,null)&&active[7]>=0;bool pass=persisted&&hidden&&visible&&Mathf.Abs(PlayerMovement.GetMovementForce(100,fan)-physics)<.001f;result.checks++;if(!pass)result.failures++;Debug.Log("ABILITY "+(pass?"PASS ":"FAIL ")+"skill display mode="+mode+" persisted="+persisted+" hidden="+hidden+" restoredSkillState="+visible);}
 yield return Scene(0);ButtonUI();}
 void ButtonUI(){var toggle=fan.GetComponent(typeof(ControlBindings).Assembly.GetType("SkillAnimationToggle"));var canvas=FindObjectOfType<UnityEngine.Canvas>();var template=FindObjectOfType<UnityEngine.UI.Button>();bool pass=toggle!=null&&canvas!=null&&template!=null;if(pass){var panel=ControlsSettingsPanel.Open(canvas.transform,template,null);UnityEngine.UI.Button button=null;foreach(var b in panel.GetComponentsInChildren<UnityEngine.UI.Button>())if(b.name=="Skill Animation Toggle")button=b;var match=GameObject.Find("Match Skill Animation Toggle");pass=button!=null&&match!=null;if(match!=null){match.GetComponent<UnityEngine.UI.Button>().onClick.Invoke();pass&=!(bool)typeof(ControlBindings).GetProperty("ShowSkillAnimations").GetValue(null,null);match.GetComponent<UnityEngine.UI.Button>().onClick.Invoke();}if(button!=null){button.onClick.Invoke();pass&=!(bool)typeof(ControlBindings).GetProperty("ShowSkillAnimations").GetValue(null,null);button.onClick.Invoke();pass&=(bool)typeof(ControlBindings).GetProperty("ShowSkillAnimations").GetValue(null,null);}Destroy(panel.gameObject);}result.checks++;if(!pass)result.failures++;Debug.Log("ABILITY "+(pass?"PASS ":"FAIL ")+"in-match toggle attached and settings button toggles display");}
 IEnumerator Start(){Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=120;AudioListener.volume=0;yield return new WaitForSeconds(.2f);for(int mode=0;mode<3;mode++)foreach(bool actor in new bool[]{true,false})foreach(bool back in new bool[]{false,true})yield return Case(mode,actor,back);yield return Display();using(var output=new StreamWriter(Path.Combine(Application.dataPath,"..","startup-metrics.csv"))){output.WriteLine("actor,mode,backward,responseTime,speed100,distance100,speed200,restartTime,reverseTime,footLift,peakLean,jointError");foreach(var s in result.samples)output.WriteLine(s.actor+","+s.mode+","+s.backward+","+s.responseTime+","+s.speed100+","+s.distance100+","+s.speed200+","+s.restartTime+","+s.reverseTime+","+s.footLift+","+s.peakLean+","+s.jointError);}File.WriteAllText(Path.Combine(Application.dataPath,"..","startup-metrics.json"),JsonUtility.ToJson(result,true));Debug.Log("ABILITY COMPLETE checks="+result.checks+" failures="+result.failures);Application.Quit(result.failures==0?0:1);}
 void Update(){if(Time.realtimeSinceStartup>100){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
}
